{
  "id": "ww-00029",
  "version": "0.1",
  "concept_id": "ww-00029",
  "identity": {
    "name": "IronPop Gym",
    "tagline": "Lift Bold. Live Loud.",
    "one_line_description": "IronPop Gym is a strength training gym with a bold, energetic personality that helps everyday people build serious muscle through structured programs, expert coaching, and a community that celebrates every rep.",
    "domain": "wellness_fitness",
    "subdomain": "strength training gym",
    "voice": [
      "bold",
      "playful",
      "energetic",
      "direct",
      "motivating"
    ],
    "target_audience": "Adults aged 18\u201340 who are new to or progressing in strength training, want structured programming over random workouts, and are drawn to a gym culture that is fun, loud, and unapologetically motivating."
  },
  "pages": [
    {
      "slug": "home",
      "title": "Home",
      "role": "landing",
      "goal": "Instantly communicate IronPop's bold identity, make visitors feel the energy of the gym, and push them toward exploring programs or booking a first session.",
      "meta_description": "IronPop Gym \u2014 a strength training gym where bold programming, expert coaching, and a wildly fun community help you lift more and live louder.",
      "sections": [
        {
          "id": "home-section-1",
          "type": "hero",
          "intent": "Grab attention immediately with IronPop's loud personality and make the core value proposition crystal clear: this is a strength gym that is both serious about results and genuinely fun.",
          "eyebrow": "Strength Training, Reimagined",
          "headline": "Lift Bold. Live Loud.",
          "subheadline": "IronPop is the strength gym for people who want real results without taking themselves too seriously. Pick up heavy things. Make friends. Repeat.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "See Our Programs",
              "target_page": "programs"
            },
            {
              "label": "Book a Free Session",
              "target_page": "book"
            }
          ],
          "asset_ideas": []
        },
        {
          "id": "home-section-2",
          "type": "feature_grid",
          "intent": "Quickly communicate the three pillars that make IronPop different from a generic big-box gym, giving visitors a reason to stay and explore.",
          "eyebrow": "Why IronPop",
          "headline": "We're Not Your Average Gym",
          "subheadline": "Three things that make members stay, lift, and come back for more.",
          "body": null,
          "items": [
            {
              "title": "Structured Strength Programs",
              "description": "No guesswork. Every session follows a proven strength plan \u2014 from beginner barbell basics to advanced powerlifting blocks.",
              "metadata": {}
            },
            {
              "title": "Coaches Who Actually Coach",
              "description": "Our trainers are on the floor, not behind a desk. They watch your form, adjust your load, and celebrate your PRs like it's their own.",
              "metadata": {}
            },
            {
              "title": "A Community That Hypes You Up",
              "description": "Whether it's your first deadlift or your hundredth, the IronPop crew is loud, supportive, and genuinely excited for your wins.",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "home-section-3",
          "type": "cta",
          "intent": "Close the home page with a punchy, low-friction invitation to take the first step, converting interest into a booked session.",
          "eyebrow": "Ready to Start?",
          "headline": "Your First Session Is On Us",
          "subheadline": "Come lift with us for free. No commitment, no awkward sales pitch \u2014 just a great workout and a community worth joining.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "Book My Free Session",
              "target_page": "book"
            }
          ],
          "asset_ideas": []
        }
      ]
    },
    {
      "slug": "programs",
      "title": "Programs",
      "role": "overview",
      "goal": "Give visitors a clear, exciting overview of all training programs offered at IronPop so they can find the right fit and feel confident signing up.",
      "meta_description": "Explore IronPop Gym's strength training programs \u2014 from beginner barbell fundamentals to powerlifting prep, there's a program built for every level.",
      "sections": [
        {
          "id": "programs-section-1",
          "type": "page_header",
          "intent": "Set the tone for the Programs page and reassure visitors that whatever their level, there is a program designed for them.",
          "eyebrow": "Training Programs",
          "headline": "Find Your Program. Own Your Lift.",
          "subheadline": "Every IronPop program is built around progressive overload, expert coaching, and a whole lot of fun. Pick your level and let's go.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "programs-section-2",
          "type": "item_grid",
          "intent": "Present each training program as its own card with enough detail for visitors to self-select the right fit, driving them toward booking.",
          "eyebrow": "All Programs",
          "headline": "Six Programs. One Goal: Getting Stronger.",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Barbell Basics",
              "description": "The perfect starting point. Learn the squat, deadlift, bench, and overhead press with hands-on coaching in a small group setting. 8-week cycle.",
              "metadata": {
                "level": "Beginner",
                "duration": "8 weeks",
                "sessions_per_week": "3x"
              }
            },
            {
              "title": "Iron Foundation",
              "description": "Build a complete strength base with compound lifts, accessory work, and mobility drills. Designed for those past the basics and ready to load up.",
              "metadata": {
                "level": "Intermediate",
                "duration": "12 weeks",
                "sessions_per_week": "4x"
              }
            },
            {
              "title": "Pop Powerlifting",
              "description": "A full powerlifting block with periodized programming, competition prep options, and weekly technique reviews. Squat. Bench. Deadlift. Dominate.",
              "metadata": {
                "level": "Advanced",
                "duration": "16 weeks",
                "sessions_per_week": "4\u20135x"
              }
            },
            {
              "title": "Strength & Conditioning",
              "description": "Combines heavy lifting with conditioning circuits for members who want to be strong and athletic. High energy, high output.",
              "metadata": {
                "level": "Intermediate",
                "duration": "10 weeks",
                "sessions_per_week": "4x"
              }
            },
            {
              "title": "Open Barbell Club",
              "description": "Drop-in strength sessions with a coach on the floor. No fixed program \u2014 just structured open lifting time for members who know what they're doing.",
              "metadata": {
                "level": "All Levels",
                "duration": "Ongoing",
                "sessions_per_week": "Flexible"
              }
            },
            {
              "title": "1-on-1 Coaching",
              "description": "Fully personalized programming and coaching tailored to your goals, schedule, and body. The fastest path to your strongest self.",
              "metadata": {
                "level": "All Levels",
                "duration": "Custom",
                "sessions_per_week": "Custom"
              }
            }
          ],
          "ctas": [
            {
              "label": "Book a Free Intro Session",
              "target_page": "book"
            }
          ],
          "asset_ideas": []
        },
        {
          "id": "programs-section-3",
          "type": "cta",
          "intent": "Encourage visitors who are still deciding to take a low-risk first step by booking a free intro session rather than committing to a full program upfront.",
          "eyebrow": "Not Sure Where to Start?",
          "headline": "Let a Coach Point You in the Right Direction",
          "subheadline": "Book a free 30-minute intro session and we'll match you with the right program for your goals, experience, and schedule.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "Book My Free Intro",
              "target_page": "book"
            }
          ],
          "asset_ideas": []
        }
      ]
    },
    {
      "slug": "pricing",
      "title": "Pricing",
      "role": "conversion",
      "goal": "Present membership and program pricing in a clear, confident way that removes hesitation and motivates visitors to commit.",
