      "sections": [
        {
          "id": "pricing-section-1",
          "type": "page_header",
          "intent": "Frame pricing as a straightforward, honest conversation \u2014 no tricks, no fine print \u2014 to build trust before visitors see the numbers.",
          "eyebrow": "Membership & Pricing",
          "headline": "Straight-Up Pricing. Zero Nonsense.",
          "subheadline": "Pick the plan that fits your life. Every membership includes access to coached sessions, open gym, and the loudest community in town.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "pricing-section-2",
          "type": "pricing",
          "intent": "Display the three membership tiers clearly so visitors can quickly compare options and choose the one that matches their goals and budget.",
          "eyebrow": "Membership Plans",
          "headline": "Three Plans. All Gains.",
          "subheadline": null,
          "body": null,
          "items": [
            {
