}

.pricing-card__name {
  font-family: var(--f-display);
  font-size: 28px;
  margin-bottom: 16px;
}

.pricing-card__desc {
  font-size: 15px;
  margin-bottom: 24px;
  flex-grow: 1;
}

.pricing-card__best-for {
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: 16px;
}

.pricing-cards-section__cta {
  display: flex;
  justify-content: center;
  margin-top: 64px;
}

/* ============================================
   FAQ
   ============================================ */
.faq-section {
  background: var(--peach);
  padding: 96px 32px;
  position: relative;
  overflow: hidden;
}

.faq-section__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 38fr 4fr 58fr;
  gap: 0;
  position: relative;
  z-index: 2;
}

.faq-section__head {
  padding-right: 24px;
}

.faq-section__head .eyebrow {
  color: var(--purple);
  margin-bottom: 12px;
}

.faq-section__head h2 {
  font-size: clamp(36px, 4vw, 48px);
  margin-bottom: 32px;
}

.faq-section__head .squiggle-block {
  width: 180px;
  height: 140px;
  position: relative;
}

.faq-section__head .squiggle-block .dot {
  position: absolute;
  bottom: 4px;
  right: 12px;
  width: 40px;
  height: 40px;
  background: var(--yellow);
  border-radius: 50%;
}

.faq-list {
  grid-column: 3;
  border-top: 1.5px solid var(--black);
}

.faq-item {
  padding: 20px 0;
  border-bottom: 1.5px solid var(--black);
}

.faq-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.faq-item h3 {
  font-family: var(--f-body);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0;
  line-height: 1.4;
  margin-bottom: 8px;
}

.faq-item p {
  font-size: 16px;
  max-width: 56ch;
}

.faq-item__callout {
  display: inline-block;
  margin-top: 8px;
  font-family: var(--f-accent);
  font-size: 13px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--coral);
}

.faq-section__bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.faq-section__bg span { position: absolute; }
.faq-section__bg .b1 { top: 8%; right: 6%; width: 28px; height: 24px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.faq-section__bg .b2 { top: 16%; right: 16%; width: 24px; height: 24px; background: var(--teal); border-radius: 50%; }
.faq-section__bg .b3 { bottom: 14%; left: 6%; width: 28px; height: 28px; background: var(--white); border: 2px solid var(--black); }
.faq-section__bg .b4 { bottom: 8%; left: 18%; width: 24px; height: 22px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); }

/* ============================================
   STORIES PAGE
   ============================================ */
/* page header for stories */
.stories-header {
  background: var(--cream);
  position: relative;
  overflow: hidden;
}

.stories-header__band {
  height: 56px;
  background: var(--yellow);
  border-bottom: 3px solid var(--black);
}

.stories-header__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 48px 32px 64px;
  display: grid;
  grid-template-columns: 58fr 42fr;
  gap: 24px;
  position: relative;
}

.stories-header__left .eyebrow {
  margin-bottom: 24px;
}

.stories-header__left h1 {
  font-size: clamp(48px, 6.5vw, 72px);
  line-height: 1.1;
}

.stories-header__left h1 .third {
  color: var(--coral);
}

.stories-header__left p {
  font-size: 18px;
  max-width: 52ch;
  margin-top: 24px;
}

.stories-header__shapes {
  position: relative;
  min-height: 280px;
}

.stories-header__shapes span {
  position: absolute;
}

.stories-header__shapes .a { top: 0; right: -40px; width: 180px; height: 180px; background: var(--peach); border-radius: 50%; }
.stories-header__shapes .b { top: 80px; left: -20px; width: 90px; height: 90px; background: var(--teal); border-radius: 50%; }
.stories-header__shapes .c { top: 60px; right: 80px; width: 60px; height: 60px; background: var(--yellow); border-radius: 50%; }
.stories-header__shapes .d { bottom: 8px; left: 80px; width: 60px; height: 50px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.stories-header__shapes .e { bottom: 30px; right: 16px; width: 60px; height: 60px; background: var(--peach); transform: rotate(45deg); }

.stories-header__shapes svg.zig {
  position: absolute;
  bottom: 24px;
  left: 24px;
  width: 100px;
  height: 30px;
}

/* Stories testimonial signature moment */
.testimonial-signature {
  position: relative;
  border-top: 4px solid var(--black);
  border-bottom: 4px solid var(--black);
}

.testimonial-signature__split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  position: relative;
  min-height: 480px;
}

.testimonial-signature__split--coral { background: var(--coral); }
.testimonial-signature__split--purple { background: var(--purple); }

.testimonial-signature__split .left,
.testimonial-signature__split .right {
  padding: 80px 64px 72px;
  position: relative;
}

.testimonial-signature__split .left {
  background: var(--coral);
}

.testimonial-signature__split .right {
  background: var(--purple);
}

.testimonial-signature__quote {
  position: absolute;
  top: 40px;
  left: 64px;
  right: 64px;
  bottom: 72px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: center;
  pointer-events: none;
}

.testimonial-signature__quote .eyebrow {
  color: var(--yellow);
  margin-bottom: 24px;
}

.testimonial-signature__quote h2 {
  font-size: clamp(40px, 6.5vw, 80px);
  color: var(--white);
  line-height: 1.05;
}

.testimonial-signature__sub {
  background: var(--cream);
  padding: 64px 80px 80px;
}

.testimonial-signature__sub h3 {
  font-size: clamp(24px, 3vw, 32px);
  color: var(--purple);
  margin-bottom: 16px;
}

.testimonial-signature__sub p {
  font-size: 17px;
  max-width: 64ch;
}

.testimonial-signature__sub::after {
  content: "";
  display: block;
  width: 120px;
  height: 4px;
  background: var(--coral);
  margin-top: 32px;
}

/* Stories grid */
.stories-grid-section {
  background: var(--cream);
  padding: 80px 32px 0;
  text-align: center;
  position: relative;
}

.stories-grid-section__inner {
  max-width: 1080px;
  margin: 0 auto;
}

.stories-grid-section h2 {
  font-size: clamp(36px, 4.5vw, 56px);
  margin-top: 16px;
  margin-bottom: 48px;
}

.story-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  text-align: left;
}

.story-card {
  background: var(--white);
  border: 2px solid var(--black);
  display: flex;
  flex-direction: column;
}

.story-card__band {
  height: 80px;
  display: grid;
  place-items: center;
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  font-weight: 700;
  text-transform: uppercase;
  text-align: center;
  padding: 0 16px;
}

.story-card__band--coral  { background: var(--coral);  color: var(--white); }
.story-card__band--teal   { background: var(--teal);   color: var(--white); }
.story-card__band--yellow { background: var(--yellow); color: var(--black); }
.story-card__band--purple { background: var(--purple); color: var(--white); }

.story-card__body {
  padding: 24px;
}

.story-card__body h3 {
  font-size: 24px;
  line-height: 1.2;
  margin-bottom: 12px;
}

.story-card__body p {
  font-size: 16px;
  margin-bottom: 16px;
}

.story-card__meta {
  border-top: 1px solid var(--peach);
  padding-top: 16px;
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--peach);
}

.story-card__meta strong {
  color: var(--black);
  font-weight: 700;
}

.stories-grid-section__divider {
  margin: 48px auto 0;
  max-width: 240px;
  display: block;
}

.stories-cta-bar {
  background: var(--yellow);
  border-top: 4px solid var(--black);
  padding: 48px 32px;
  text-align: center;
  margin-top: 48px;
}

.stories-cta-bar h3 {
  font-size: clamp(28px, 3vw, 40px);
  margin-bottom: 20px;
}

/* ============================================
   BOOK PAGE
   ============================================ */
.book-header {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 480px;
  border-bottom: 4px solid var(--black);
  position: relative;
}

.book-header__cream,
.book-header__coral {
  padding: 64px 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
}

.book-header__cream {
  background: var(--cream);
}

.book-header__coral {
  background: var(--coral);
  color: var(--white);
  padding-left: 40px;
}

.book-header__cream .eyebrow {
  color: var(--teal);
  margin-bottom: 24px;
}

.book-header__cream p {
  font-size: 17px;
  max-width: 380px;
  margin-top: 20px;
}

.book-header__coral h1 {
  line-height: 1;
}

.book-header__coral .l1 {
  font-size: clamp(40px, 5vw, 64px);
  display: block;
}

.book-header__coral .l2 {
  font-size: clamp(64px, 9vw, 110px);
  display: block;
  color: var(--yellow);
  margin-left: -24px;
  line-height: 0.9;
  margin-top: 4px;
  margin-bottom: 4px;
}

.book-header__coral .l3 {
  font-size: clamp(40px, 5vw, 64px);
  display: block;
}

.book-header__decor {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.book-header__decor span,
.book-header__decor svg {
  position: absolute;
}

.book-header__decor .circ { width: 32px; height: 32px; background: var(--teal); border-radius: 50%; left: calc(50% - 16px); top: 15%; }
.book-header__decor .tri  { width: 28px; height: 26px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); right: 38%; bottom: 12%; }
.book-header__decor .sq1  { left: 30%; top: 20%; width: 200px; height: 80px; }
.book-header__decor .sq2  { left: 45%; top: 70%; width: 120px; height: 50px; }

/* Booking form section */
.booking-section {
  background: var(--cream);
  padding: 96px 32px 80px;
}

.booking-section__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: stretch;
}

.booking-form {
  background: var(--white);
  border: 3px solid var(--black);
  border-radius: 16px;
  padding: 40px;
  position: relative;
}

.booking-form__sticker {
  position: absolute;
  top: -10px;
  right: 32px;
  width: 24px;
  height: 24px;
  background: var(--yellow);
  border: 2px solid var(--black);
  border-radius: 50%;
}

.booking-form .eyebrow {
  color: var(--coral);
}

.booking-form h2 {
  font-size: clamp(36px, 4vw, 52px);
  margin-top: 12px;
}

.booking-form .sub {
  font-size: 16px;
  margin-top: 16px;
}

.booking-form .body {
  font-size: 15px;
  margin-top: 12px;
  color: rgba(26, 26, 26, 0.7);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-top: 24px;
}

.form-grid--full { grid-template-columns: 1fr; }

.field {
  display: flex;
  flex-direction: column;
}

.field label {
  font-family: var(--f-body);
  font-weight: 500;
  font-size: 13px;
  margin-bottom: 8px;
}

.field input,
.field select,
.field textarea {
  font-family: var(--f-body);
  font-size: 15px;
  color: var(--black);
  padding: 12px 14px;
  border: 2px solid var(--black);
  border-radius: 8px;
  background: var(--white);
  height: 48px;
  outline: none;
  transition: background 0.15s ease, box-shadow 0.15s ease;
}

.field textarea {
  height: auto;
  min-height: 86px;
  resize: vertical;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  background: var(--cream);
  box-shadow: 0 0 0 3px rgba(255, 214, 0, 0.5);
}

.day-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.day-pills label {
  cursor: pointer;
}

.day-pills input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.day-pills span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--f-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: var(--cream);
  border: 2px solid var(--black);
  padding: 8px 14px;
  border-radius: 999px;
  transition: background 0.12s ease, color 0.12s ease;
}

.day-pills input:checked + span {
  background: var(--yellow);
  color: var(--black);
}

.booking-info {
  background: var(--teal);
  color: var(--white);
  border: 3px solid var(--black);
  border-radius: 16px;
  padding: 32px;
  position: relative;
  overflow: hidden;
}

.booking-info__star {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 22px;
  height: 22px;
  border: 2px solid var(--yellow);
  transform: rotate(45deg);
}

.booking-info__list {
  position: relative;
  z-index: 2;
}

.booking-info__item + .booking-info__item {
  margin-top: 32px;
  padding-top: 32px;
  border-top: 1px solid rgba(255, 255, 255, 0.3);
}

.booking-info__item h3 {
  font-size: 22px;
  color: var(--white);
  margin-bottom: 6px;
}

.booking-info__item p {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.92);
}

.booking-info__squiggle {
  position: absolute;
  bottom: -8px;
  right: -8px;
  width: 120px;
  height: 80px;
  pointer-events: none;
}

/* Book section 3 */
.book-cta {
  background: var(--purple);
  color: var(--white);
  padding: 96px 32px;
  position: relative;
  overflow: hidden;
}

.book-cta__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 32px;
  position: relative;
  z-index: 2;
}

.book-cta__content .eyebrow {
  color: var(--yellow);
  margin-bottom: 14px;
}

.book-cta__content h2 {
  font-size: clamp(28px, 3.5vw, 40px);
  margin-bottom: 16px;
  max-width: 18ch;
  line-height: 1.1;
}

.book-cta__content p {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.85);
  max-width: 52ch;
  margin-bottom: 28px;
}

.book-cta__content p .em {
  color: var(--yellow);
  font-weight: 700;
}

.book-cta__buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.book-cta__decor {
  position: relative;
  min-height: 240px;
}

.book-cta__decor span,
.book-cta__decor svg {
  position: absolute;
}

.book-cta__decor .c1 { width: 80px; height: 80px; background: var(--teal); border-radius: 50%; top: 30%; left: 25%; }
.book-cta__decor .c2 { width: 60px; height: 40px; border: 3px solid var(--yellow); transform: rotate(15deg); top: 55%; left: 60%; }
.book-cta__decor .c3 { width: 40px; height: 36px; background: var(--peach); clip-path: polygon(50% 0, 100% 100%, 0 100%); bottom: 15%; left: 75%; }
.book-cta__decor svg  { top: 18%; left: 40%; width: 200px; }

