/* IronPop Gym - Memphis Playful design system */

@import url('https://fonts.googleapis.com/css2?family=Fredoka+One&family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@400;500;700&display=swap');

:root {
  --cream: #FFF8EC;
  --coral: #FF4D4D;
  --teal: #00C2B2;
  --yellow: #FFD600;
  --purple: #7B2FBE;
  --black: #1A1A1A;
  --white: #FFFFFF;
  --peach: #FFB085;

  --f-display: 'Fredoka One', system-ui, sans-serif;
  --f-body: 'DM Sans', system-ui, sans-serif;
  --f-accent: 'Space Grotesk', system-ui, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--f-body);
  background: var(--cream);
  color: var(--black);
  font-size: 16px;
  line-height: 1.65;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

img, svg {
  display: block;
  max-width: 100%;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul {
  list-style: none;
}

/* ============================================
   GLOBAL TYPOGRAPHY
   ============================================ */
.eyebrow {
  font-family: var(--f-accent);
  font-weight: 500;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  display: inline-block;
}

.eyebrow.pill {
  border: 1.5px solid currentColor;
  padding: 4px 10px;
  border-radius: 999px;
}

.eyebrow.with-rule::before {
  content: "";
  display: inline-block;
  width: 40px;
  height: 2px;
  background: currentColor;
  vertical-align: middle;
  margin-right: 10px;
  position: relative;
  top: -2px;
}

h1, h2, h3, h4 {
  font-family: var(--f-display);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

/* ============================================
   BUTTONS
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--f-accent);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  height: 48px;
  padding: 0 24px;
  border-radius: 999px;
  background: var(--coral);
  color: var(--white);
  transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;
  border: 2px solid transparent;
  white-space: nowrap;
}

.btn:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 0 6px 0 var(--black);
}

.btn--dark {
  background: var(--black);
  color: var(--white);
}

.btn--yellow {
  background: var(--yellow);
  color: var(--black);
}

.btn--outline-light {
  background: transparent;
  color: var(--white);
  border: 3px solid var(--white);
  border-radius: 0;
}

.btn--outline-light:hover {
  background: var(--white);
  color: var(--purple);
}

.btn--block {
  width: 100%;
  height: 56px;
  font-family: var(--f-display);
  letter-spacing: 0.02em;
  font-size: 18px;
  border: 3px solid var(--black);
  border-radius: 0;
}

.btn--block:hover {
  background: var(--black);
  color: var(--white);
  transform: none;
  box-shadow: none;
}

.btn--rect {
  border-radius: 0;
  border: 3px solid var(--black);
  height: 52px;
  font-family: var(--f-display);
  font-size: 16px;
  letter-spacing: 0.01em;
}

.btn--rect:hover {
  background: var(--white);
  color: var(--black);
  transform: none;
  box-shadow: none;
}

/* ============================================
   SITE HEADER / NAV
   ============================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--cream);
  border-bottom: 3px solid var(--black);
}

.site-header__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 16px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--f-display);
  font-size: 22px;
  color: var(--black);
}

.brand__mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  background: var(--coral);
  border: 2.5px solid var(--black);
  border-radius: 8px;
  transform: rotate(-4deg);
}

.brand:hover .brand__mark {
  background: var(--yellow);
  transition: background 0.2s ease;
}

.nav__list {
  display: flex;
  gap: 8px;
  align-items: center;
}

.nav__link {
  font-family: var(--f-accent);
  font-size: 13px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--black);
  transition: background 0.15s ease, color 0.15s ease;
}

.nav__link:hover {
  background: var(--black);
  color: var(--cream);
}

.nav__link--active {
  background: var(--purple);
  color: var(--white);
}

.nav__cta {
  background: var(--coral);
  color: var(--white);
  border: 2px solid var(--black);
  padding: 10px 18px;
  border-radius: 999px;
  font-family: var(--f-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: transform 0.18s ease;
}

.nav__cta:hover {
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0 var(--black);
}

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  border: 2px solid var(--black);
  border-radius: 8px;
  background: var(--cream);
  position: relative;
}

.nav-toggle::before,
.nav-toggle::after,
.nav-toggle span {
  content: "";
  position: absolute;
  left: 8px;
  right: 8px;
  height: 3px;
  background: var(--black);
}

.nav-toggle::before { top: 11px; }
.nav-toggle span    { top: 18px; display: block; }
.nav-toggle::after  { top: 25px; }

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--black);
  color: var(--cream);
  padding: 64px 32px 32px;
  position: relative;
  overflow: hidden;
}

.site-footer__inner {
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.site-footer__top {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 2px solid rgba(255, 248, 236, 0.18);
}

.site-footer__brand h3 {
  font-size: 32px;
  margin-bottom: 8px;
  color: var(--cream);
}

.site-footer__brand p {
  color: rgba(255, 248, 236, 0.7);
  font-size: 15px;
  max-width: 320px;
}

.site-footer__brand .tagline {
  display: inline-block;
  background: var(--yellow);
  color: var(--black);
  font-family: var(--f-accent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 4px 10px;
  margin-bottom: 16px;
  transform: rotate(-3deg);
}

.site-footer h4 {
  font-family: var(--f-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--yellow);
  margin-bottom: 16px;
}

.site-footer ul li {
  margin-bottom: 8px;
}

.site-footer ul a {
  color: var(--cream);
  font-size: 15px;
  transition: color 0.15s ease;
}

.site-footer ul a:hover {
  color: var(--coral);
}

.site-footer__bottom {
  margin-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-family: var(--f-accent);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255, 248, 236, 0.55);
}

.site-footer__bottom .socials {
  display: flex;
  gap: 12px;
}

.site-footer__bottom .socials a {
  width: 36px;
  height: 36px;
  border: 1.5px solid rgba(255, 248, 236, 0.4);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--cream);
  transition: background 0.15s ease, color 0.15s ease;
}

.site-footer__bottom .socials a:hover {
  background: var(--coral);
  border-color: var(--coral);
  color: var(--white);
}

.site-footer__bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.08;
}

/* ============================================
   SHARED SECTION SCAFFOLD
   ============================================ */
.section {
  position: relative;
  overflow: hidden;
}

.section__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 96px 32px;
  position: relative;
}

/* ============================================
   HERO (home-section-1) - signature split panel
   ============================================ */
.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: calc(100vh - 80px);
  position: relative;
  border-bottom: 4px solid var(--black);
}

.hero__panel {
  padding: 64px 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.hero__panel--coral {
  background: var(--coral);
  color: var(--white);
}

.hero__panel--cream {
  background: var(--cream);
  color: var(--black);
}

.hero__title {
  font-size: clamp(56px, 9vw, 120px);
  line-height: 0.9;
  text-transform: uppercase;
  margin-top: 16px;
}

.hero__title--bleed {
  /* subtle overflow bleed effect */
  margin-right: -16px;
  position: relative;
  z-index: 2;
}

.hero__sub {
  font-size: 18px;
  max-width: 52ch;
  margin-top: 24px;
  line-height: 1.65;
}

.hero__ctas {
  display: flex;
  gap: 16px;
  margin-top: 32px;
  flex-wrap: wrap;
}

.hero__squiggle {
  position: absolute;
  top: 55%;
  right: -60px;
  width: 140px;
  height: auto;
  z-index: 5;
  pointer-events: none;
  transform: translateY(-50%);
}

.hero__confetti {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.hero__confetti span {
  position: absolute;
}

.hero__confetti .c1 { top: 12%; right: 18%; width: 26px; height: 26px; background: var(--teal); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.hero__confetti .c2 { top: 22%; right: 8%;  width: 22px; height: 22px; background: var(--yellow); border-radius: 50%; }
.hero__confetti .c3 { top: 32%; right: 26%; width: 28px; height: 12px; background: var(--peach); transform: rotate(-12deg); }

/* ============================================
   FEATURE GRID (home-section-2)
   ============================================ */
.feature-grid {
  background: var(--cream);
  padding: 96px 32px;
  position: relative;
}

.feature-grid__container {
  max-width: 1200px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.feature-grid__header {
  display: grid;
  grid-template-columns: 58fr 4fr 38fr;
  gap: 0;
  align-items: end;
  margin-bottom: 56px;
}

.feature-grid__head-left .eyebrow {
  color: var(--coral);
  margin-bottom: 12px;
}

.feature-grid__head-left h2 {
  font-size: clamp(40px, 5vw, 56px);
  color: var(--purple);
}

.feature-grid__head-right {
  grid-column: 3;
  font-size: 18px;
  color: var(--black);
  max-width: 36ch;
  padding-bottom: 8px;
}

.feature-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  position: relative;
  z-index: 2;
}

.feature-card {
  background: var(--white);
  border: 1.5px solid var(--black);
  border-top: none;
  padding: 40px 32px 32px;
  position: relative;
}

.feature-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 8px;
}

.feature-card[data-accent="teal"]::before   { background: var(--teal); }
.feature-card[data-accent="yellow"]::before { background: var(--yellow); }
.feature-card[data-accent="coral"]::before  { background: var(--coral); }

.feature-card__stamp {
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  margin-bottom: 12px;
}

.feature-card[data-accent="teal"] .feature-card__stamp   { color: var(--teal); }
.feature-card[data-accent="yellow"] .feature-card__stamp { color: #c89e00; }
.feature-card[data-accent="coral"] .feature-card__stamp  { color: var(--coral); }

.feature-card h3 {
  font-size: 28px;
  line-height: 1.1;
  margin-bottom: 16px;
}

.feature-card p {
  font-size: 16px;
  max-width: 48ch;
}

.feature-grid__confetti {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.feature-grid__confetti span {
  position: absolute;
  background: var(--peach);
}

.feature-grid__confetti .x1 { top: 12%; left: 8%;  width: 16px; height: 16px; border-radius: 50%; }
.feature-grid__confetti .x2 { top: 8%;  right: 28%; width: 16px; height: 16px; border-radius: 50%; }
.feature-grid__confetti .x3 { top: 24%; left: 47%; width: 20px; height: 20px; transform: rotate(45deg); }
.feature-grid__confetti .x4 { bottom: 16%; right: 8%; width: 32px; height: 8px; }
.feature-grid__confetti .x5 { bottom: 24%; left: 12%; width: 16px; height: 16px; border-radius: 50%; }

/* ============================================
   CTA closing block (Home, Programs sec3)
   ============================================ */
.cta-block {
  background: var(--purple);
  color: var(--white);
  padding: 96px 32px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-block__inner {
  max-width: 720px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.cta-block .eyebrow {
  color: var(--yellow);
  margin-bottom: 20px;
}

.cta-block h2 {
  font-size: clamp(40px, 5.5vw, 60px);
  color: var(--white);
  margin-bottom: 20px;
  line-height: 1;
}

.cta-block p {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.85);
  max-width: 56ch;
  margin: 0 auto 32px;
}

.cta-block__circles span {
  position: absolute;
  background: var(--peach);
  border-radius: 50%;
