.hero__squiggle {
  top: auto;
  bottom: -50px;
  left: 50%;
  transform: translateX(-50%) rotate(90deg);
}

tool_use_result.originalFile:
/* IronPop Gym - Memphis Playful design system */

@import url('https://fonts.googleapis.com/css2?family=Fredoka+One&family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@400;500;700&display=swap');

:root {
  --cream: #FFF8EC;
  --coral: #FF4D4D;
  --teal: #00C2B2;
  --yellow: #FFD600;
  --purple: #7B2FBE;
  --black: #1A1A1A;
  --white: #FFFFFF;
  --peach: #FFB085;

  --f-display: 'Fredoka One', system-ui, sans-serif;
  --f-body: 'DM Sans', system-ui, sans-serif;
  --f-accent: 'Space Grotesk', system-ui, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--f-body);
  background: var(--cream);
  color: var(--black);
  font-size: 16px;
  line-height: 1.65;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

img, svg {
  display: block;
  max-width: 100%;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul {
  list-style: none;
}

/* ============================================
   GLOBAL TYPOGRAPHY
   ============================================ */
.eyebrow {
  font-family: var(--f-accent);
  font-weight: 500;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  display: inline-block;
}

.eyebrow.pill {
  border: 1.5px solid currentColor;
  padding: 4px 10px;
  border-radius: 999px;
}

.eyebrow.with-rule::before {
  content: "";
  display: inline-block;
  width: 40px;
  height: 2px;
  background: currentColor;
  vertical-align: middle;
  margin-right: 10px;
  position: relative;
  top: -2px;
}

h1, h2, h3, h4 {
  font-family: var(--f-display);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

/* ============================================
   BUTTONS
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--f-accent);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  height: 48px;
  padding: 0 24px;
  border-radius: 999px;
  background: var(--coral);
  color: var(--white);
  transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;
  border: 2px solid transparent;
  white-space: nowrap;
}

.btn:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 0 6px 0 var(--black);
}

.btn--dark {
  background: var(--black);
  color: var(--white);
}

.btn--yellow {
  background: var(--yellow);
  color: var(--black);
}

.btn--outline-light {
  background: transparent;
  color: var(--white);
  border: 3px solid var(--white);
  border-radius: 0;
}

.btn--outline-light:hover {
  background: var(--white);
  color: var(--purple);
}

.btn--block {
  width: 100%;
  height: 56px;
  font-family: var(--f-display);
  letter-spacing: 0.02em;
  font-size: 18px;
  border: 3px solid var(--black);
  border-radius: 0;
}

.btn--block:hover {
  background: var(--black);
  color: var(--white);
  transform: none;
  box-shadow: none;
}

.btn--rect {
  border-radius: 0;
  border: 3px solid var(--black);
  height: 52px;
  font-family: var(--f-display);
  font-size: 16px;
  letter-spacing: 0.01em;
}

.btn--rect:hover {
  background: var(--white);
  color: var(--black);
  transform: none;
  box-shadow: none;
}

/* ============================================
   SITE HEADER / NAV
   ============================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--cream);
  border-bottom: 3px solid var(--black);
}

.site-header__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 16px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--f-display);
  font-size: 22px;
  color: var(--black);
}

.brand__mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  background: var(--coral);
  border: 2.5px solid var(--black);
  border-radius: 8px;
  transform: rotate(-4deg);
}

.brand:hover .brand__mark {
  background: var(--yellow);
  transition: background 0.2s ease;
}

.nav__list {
  display: flex;
  gap: 8px;
  align-items: center;
}

.nav__link {
  font-family: var(--f-accent);
  font-size: 13px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--black);
  transition: background 0.15s ease, color 0.15s ease;
}

.nav__link:hover {
  background: var(--black);
  color: var(--cream);
}

.nav__link--active {
  background: var(--purple);
  color: var(--white);
}

.nav__cta {
  background: var(--coral);
  color: var(--white);
  border: 2px solid var(--black);
  padding: 10px 18px;
  border-radius: 999px;
  font-family: var(--f-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: transform 0.18s ease;
}

.nav__cta:hover {
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0 var(--black);
}

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  border: 2px solid var(--black);
  border-radius: 8px;
  background: var(--cream);
  position: relative;
}

.nav-toggle::before,
.nav-toggle::after,
.nav-toggle span {
  content: "";
  position: absolute;
  left: 8px;
  right: 8px;
  height: 3px;
  background: var(--black);
}

.nav-toggle::before { top: 11px; }
.nav-toggle span    { top: 18px; display: block; }
.nav-toggle::after  { top: 25px; }

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--black);
  color: var(--cream);
  padding: 64px 32px 32px;
  position: relative;
  overflow: hidden;
}

.site-footer__inner {
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.site-footer__top {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 2px solid rgba(255, 248, 236, 0.18);
}

.site-footer__brand h3 {
  font-size: 32px;
  margin-bottom: 8px;
  color: var(--cream);
}

.site-footer__brand p {
  color: rgba(255, 248, 236, 0.7);
  font-size: 15px;
  max-width: 320px;
}

.site-footer__brand .tagline {
  display: inline-block;
  background: var(--yellow);
  color: var(--black);
  font-family: var(--f-accent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 4px 10px;
  margin-bottom: 16px;
  transform: rotate(-3deg);
}

.site-footer h4 {
  font-family: var(--f-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--yellow);
  margin-bottom: 16px;
}

.site-footer ul li {
  margin-bottom: 8px;
}

.site-footer ul a {
  color: var(--cream);
  font-size: 15px;
  transition: color 0.15s ease;
}

.site-footer ul a:hover {
  color: var(--coral);
}

.site-footer__bottom {
  margin-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-family: var(--f-accent);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255, 248, 236, 0.55);
}

.site-footer__bottom .socials {
  display: flex;
  gap: 12px;
}

.site-footer__bottom .socials a {
  width: 36px;
  height: 36px;
  border: 1.5px solid rgba(255, 248, 236, 0.4);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--cream);
  transition: background 0.15s ease, color 0.15s ease;
}

.site-footer__bottom .socials a:hover {
  background: var(--coral);
  border-color: var(--coral);
  color: var(--white);
}

.site-footer__bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.08;
}

/* ============================================
   SHARED SECTION SCAFFOLD
   ============================================ */
.section {
  position: relative;
  overflow: hidden;
}

.section__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 96px 32px;
  position: relative;
}

/* ============================================
   HERO (home-section-1) - signature split panel
   ============================================ */
.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: calc(100vh - 80px);
  position: relative;
  border-bottom: 4px solid var(--black);
}

.hero__panel {
  padding: 64px 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.hero__panel--coral {
  background: var(--coral);
  color: var(--white);
}

.hero__panel--cream {
  background: var(--cream);
  color: var(--black);
}

.hero__title {
  font-size: clamp(56px, 9vw, 120px);
  line-height: 0.9;
  text-transform: uppercase;
  margin-top: 16px;
}

.hero__title--bleed {
  /* subtle overflow bleed effect */
  margin-right: -16px;
  position: relative;
  z-index: 2;
}

.hero__sub {
  font-size: 18px;
  max-width: 52ch;
  margin-top: 24px;
  line-height: 1.65;
}

.hero__ctas {
  display: flex;
  gap: 16px;
  margin-top: 32px;
  flex-wrap: wrap;
}

.hero__squiggle {
  position: absolute;
  top: 55%;
  left: 50%;
  width: 140px;
  height: auto;
  z-index: 5;
  pointer-events: none;
  transform: translate(-50%, -50%);
}

.hero__confetti {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.hero__confetti span {
  position: absolute;
}

.hero__confetti .c1 { top: 12%; right: 18%; width: 26px; height: 26px; background: var(--teal); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.hero__confetti .c2 { top: 22%; right: 8%;  width: 22px; height: 22px; background: var(--yellow); border-radius: 50%; }
.hero__confetti .c3 { top: 32%; right: 26%; width: 28px; height: 12px; background: var(--peach); transform: rotate(-12deg); }

/* ============================================
   FEATURE GRID (home-section-2)
   ============================================ */
.feature-grid {
  background: var(--cream);
  padding: 96px 32px;
  position: relative;
}

.feature-grid__container {
  max-width: 1200px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.feature-grid__header {
  display: grid;
  grid-template-columns: 58fr 4fr 38fr;
  gap: 0;
  align-items: end;
  margin-bottom: 56px;
}

.feature-grid__head-left .eyebrow {
  color: var(--coral);
  margin-bottom: 12px;
}

.feature-grid__head-left h2 {
  font-size: clamp(40px, 5vw, 56px);
  color: var(--purple);
}

.feature-grid__head-right {
  grid-column: 3;
  font-size: 18px;
  color: var(--black);
  max-width: 36ch;
  padding-bottom: 8px;
}

.feature-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  position: relative;
  z-index: 2;
}

.feature-card {
  background: var(--white);
  border: 1.5px solid var(--black);
  border-top: none;
  padding: 40px 32px 32px;
  position: relative;
}

.feature-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 8px;
}

.feature-card[data-accent="teal"]::before   { background: var(--teal); }
.feature-card[data-accent="yellow"]::before { background: var(--yellow); }
.feature-card[data-accent="coral"]::before  { background: var(--coral); }

.feature-card__stamp {
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  margin-bottom: 12px;
}

.feature-card[data-accent="teal"] .feature-card__stamp   { color: var(--teal); }
.feature-card[data-accent="yellow"] .feature-card__stamp { color: #c89e00; }
.feature-card[data-accent="coral"] .feature-card__stamp  { color: var(--coral); }

.feature-card h3 {
  font-size: 28px;
  line-height: 1.1;
  margin-bottom: 16px;
}

.feature-card p {
  font-size: 16px;
  max-width: 48ch;
}

.feature-grid__confetti {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.feature-grid__confetti span {
  position: absolute;
  background: var(--peach);
}

.feature-grid__confetti .x1 { top: 12%; left: 8%;  width: 16px; height: 16px; border-radius: 50%; }
.feature-grid__confetti .x2 { top: 8%;  right: 28%; width: 16px; height: 16px; border-radius: 50%; }
.feature-grid__confetti .x3 { top: 24%; left: 47%; width: 20px; height: 20px; transform: rotate(45deg); }
.feature-grid__confetti .x4 { bottom: 16%; right: 8%; width: 32px; height: 8px; }
.feature-grid__confetti .x5 { bottom: 24%; left: 12%; width: 16px; height: 16px; border-radius: 50%; }

/* ============================================
   CTA closing block (Home, Programs sec3)
   ============================================ */
.cta-block {
  background: var(--purple);
  color: var(--white);
  padding: 96px 32px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-block__inner {
  max-width: 720px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.cta-block .eyebrow {
  color: var(--yellow);
  margin-bottom: 20px;
}

.cta-block h2 {
  font-size: clamp(40px, 5.5vw, 60px);
  color: var(--white);
  margin-bottom: 20px;
  line-height: 1;
}

.cta-block p {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.85);
  max-width: 56ch;
  margin: 0 auto 32px;
}

.cta-block__circles span {
  position: absolute;
  background: var(--peach);
  border-radius: 50%;
  opacity: 0.15;
  pointer-events: none;
}

.cta-block__circles .big   { width: 320px; height: 320px; right: -80px; bottom: -120px; }
.cta-block__circles .small { width: 60px;  height: 60px;  left: 10%; top: 18%; }

.cta-block__shapes {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.cta-block__shapes span {
  position: absolute;
  opacity: 0.22;
}

.cta-block__shapes .t1 { left: 6%;  top: 22%; width: 40px; height: 36px; background: var(--teal); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.cta-block__shapes .t2 { right: 8%; top: 70%; width: 32px; height: 28px; background: var(--teal); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.cta-block__shapes .d1 { left: 18%; bottom: 16%; width: 30px; height: 30px; background: var(--yellow); transform: rotate(45deg); }
.cta-block__shapes .d2 { right: 18%; top: 20%; width: 30px; height: 30px; background: var(--yellow); transform: rotate(45deg); }
.cta-block__shapes .s1 { left: 12%; top: 60%; width: 60px; height: 6px; background: var(--white); border-radius: 6px; }
.cta-block__shapes .s2 { right: 30%; top: 28%; width: 50px; height: 6px; background: var(--white); border-radius: 6px; }

/* ============================================
   PAGE HEADER - shared across multiple pages
   ============================================ */
.page-header {
  display: grid;
  grid-template-columns: 45fr 55fr;
  min-height: 480px;
  border-bottom: 4px solid var(--black);
}

.page-header--reverse {
  grid-template-columns: 55fr 45fr;
}

.page-header__panel {
  padding: 64px 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.page-header__panel--coral {
  background: var(--coral);
  color: var(--white);
}

.page-header__panel--cream {
  background: var(--cream);
  color: var(--black);
}

.page-header__panel--coral .eyebrow {
  color: var(--white);
}

.page-header__title {
  font-size: clamp(40px, 6vw, 72px);
  margin-top: 24px;
}

.page-header__sub {
  font-size: 18px;
  line-height: 1.65;
  max-width: 48ch;
}

.page-header__sub--right {
  align-self: center;
}

.page-header__yellow-band {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 56px;
  background: var(--yellow);
  z-index: 2;
}

.page-header__shape-cluster {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.page-header__shape-cluster span {
  position: absolute;
}

/* page header big squiggle on coral panel (programs) */
.page-header .corner-squiggle {
  position: absolute;
  bottom: 24px;
  right: 24px;
  width: 130px;
  height: 88px;
  pointer-events: none;
}

/* ============================================
   PROGRAMS - item grid signature
   ============================================ */
.programs-grid-section {
  background: var(--cream);
  padding: 96px 32px 80px;
  position: relative;
  overflow: hidden;
}

.programs-grid-section__inner {
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.programs-grid-section__watermark {
  position: absolute;
  left: -40px;
  top: 280px;
  font-family: var(--f-display);
  font-size: 120px;
  letter-spacing: -0.04em;
  color: var(--yellow);
  opacity: 0.22;
  transform: rotate(-90deg);
  transform-origin: left top;
  z-index: 1;
  pointer-events: none;
  user-select: none;
  white-space: nowrap;
}

.programs-grid-section__header {
  margin-bottom: 48px;
}

.programs-grid-section__header .eyebrow {
  color: var(--teal);
}

.programs-grid-section__header h2 {
  font-size: clamp(36px, 4.5vw, 56px);
  margin-top: 16px;
}

.programs-grid-section__header h2 .accent {
  color: var(--coral);
}

.program-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  position: relative;
  z-index: 2;
}

.program-card {
  padding: 32px 24px;
  border-radius: 0;
  display: flex;
  flex-direction: column;
  min-height: 320px;
  position: relative;
}

.program-card--teal  { background: var(--teal);  color: var(--white); }
.program-card--white { background: var(--white); color: var(--black); border: 2px solid var(--black); }
.program-card--black { background: var(--black); color: var(--white); }
.program-card--coral { background: var(--coral); color: var(--white); }

.program-card__badge {
  display: inline-block;
  background: var(--yellow);
  color: var(--black);
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  font-weight: 700;
  text-transform: uppercase;
  padding: 6px 12px;
  border-radius: 20px;
  align-self: flex-start;
  margin-bottom: 16px;
}

.program-card h3 {
  font-size: 28px;
  margin-bottom: 12px;
  line-height: 1.15;
}

.program-card p {
  font-size: 15px;
  margin-bottom: 24px;
  flex-grow: 1;
}

.program-card__meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: auto;
}

.program-card__chip {
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: 4px;
}

.program-card--white .program-card__chip { background: var(--black); color: var(--white); }
.program-card--teal .program-card__chip,
.program-card--black .program-card__chip,
.program-card--coral .program-card__chip { background: var(--yellow); color: var(--black); }

.programs-grid-section__cta {
  display: flex;
  justify-content: center;
  margin-top: 56px;
}

/* ============================================
   PRICING
   ============================================ */
.pricing-header {
  position: relative;
  overflow: hidden;
}

.pricing-header__zero {
  position: absolute;
  font-family: var(--f-display);
  font-size: clamp(120px, 18vw, 200px);
  color: var(--white);
  letter-spacing: -0.04em;
  transform: rotate(-4deg);
  bottom: 24px;
  left: 30%;
  z-index: 2;
  pointer-events: none;
  line-height: 1;
}

.pricing-cards-section {
  background: var(--cream);
  padding: 80px 32px 96px;
  position: relative;
  overflow: hidden;
}

.pricing-cards-section__band {
  position: absolute;
  left: 0; right: 0;
  top: 50%;
  height: 220px;
  background: var(--teal);
  transform: translateY(-50%);
  z-index: 1;
}

.pricing-cards-section__band span {
  position: absolute;
  background: var(--yellow);
}

.pricing-cards-section__band span:nth-child(1) { left: 8%;  top: 30%; width: 24px; height: 12px; }
.pricing-cards-section__band span:nth-child(2) { left: 48%; bottom: 24%; width: 24px; height: 12px; }
.pricing-cards-section__band span:nth-child(3) { right: 12%; top: 36%; width: 24px; height: 12px; }

.pricing-cards-section__inner {
  max-width: 1100px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.pricing-cards-section__header {
  text-align: center;
  margin-bottom: 56px;
}

.pricing-cards-section__header .eyebrow {
  margin-bottom: 8px;
}

.pricing-cards-section__header h2 {
  font-size: clamp(36px, 4.5vw, 56px);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  align-items: end;
}

.pricing-card {
  background: var(--white);
  border: 3px solid var(--black);
  border-radius: 16px;
  padding: 28px;
  position: relative;
  display: flex;
  flex-direction: column;
}

.pricing-card--featured {
  border-color: var(--purple);
  padding-top: 0;
  transform: translateY(-24px);
}

.pricing-card__featured-bar {
  background: var(--purple);
  color: var(--white);
  font-family: var(--f-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 12px;
  font-weight: 700;
  height: 48px;
  display: grid;
  place-items: center;
  margin: -1px -28px 24px;
  border-radius: 13px 13px 0 0;
}

.pricing-card__sticker {
  position: absolute;
  top: 24px;
  right: 24px;
  background: var(--yellow);
  color: var(--black);
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  font-weight: 700;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 4px;
  transform: rotate(4deg);
}

.pricing-card__price {
  font-family: var(--f-display);
  font-size: 56px;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
  line-height: 1;
}

.pricing-card--featured .pricing-card__price {
  color: var(--coral);
}

.pricing-card__name {
  font-family: var(--f-display);
  font-size: 28px;
  margin-bottom: 16px;
}

.pricing-card__desc {
  font-size: 15px;
  margin-bottom: 24px;
  flex-grow: 1;
}

.pricing-card__best-for {
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: 16px;
}

.pricing-cards-section__cta {
  display: flex;
  justify-content: center;
  margin-top: 64px;
}

/* ============================================
   FAQ
   ============================================ */
.faq-section {
  background: var(--peach);
  padding: 96px 32px;
  position: relative;
  overflow: hidden;
}

.faq-section__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 38fr 4fr 58fr;
  gap: 0;
  position: relative;
  z-index: 2;
}

.faq-section__head {
  padding-right: 24px;
}

.faq-section__head .eyebrow {
  color: var(--purple);
  margin-bottom: 12px;
}

.faq-section__head h2 {
  font-size: clamp(36px, 4vw, 48px);
  margin-bottom: 32px;
}

.faq-section__head .squiggle-block {
  width: 180px;
  height: 140px;
  position: relative;
}

.faq-section__head .squiggle-block .dot {
  position: absolute;
  bottom: 4px;
  right: 12px;
  width: 40px;
  height: 40px;
  background: var(--yellow);
  border-radius: 50%;
}

.faq-list {
  grid-column: 3;
  border-top: 1.5px solid var(--black);
}

.faq-item {
  padding: 20px 0;
  border-bottom: 1.5px solid var(--black);
}

.faq-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.faq-item h3 {
  font-family: var(--f-body);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0;
  line-height: 1.4;
  margin-bottom: 8px;
}

.faq-item p {
  font-size: 16px;
  max-width: 56ch;
}

.faq-item__callout {
  display: inline-block;
  margin-top: 8px;
  font-family: var(--f-accent);
  font-size: 13px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--coral);
}

.faq-section__bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.faq-section__bg span { position: absolute; }
.faq-section__bg .b1 { top: 8%; right: 6%; width: 28px; height: 24px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.faq-section__bg .b2 { top: 16%; right: 16%; width: 24px; height: 24px; background: var(--teal); border-radius: 50%; }
.faq-section__bg .b3 { bottom: 14%; left: 6%; width: 28px; height: 28px; background: var(--white); border: 2px solid var(--black); }
.faq-section__bg .b4 { bottom: 8%; left: 18%; width: 24px; height: 22px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); }

/* ============================================
   STORIES PAGE
   ============================================ */
/* page header for stories */
.stories-header {
  background: var(--cream);
  position: relative;
  overflow: hidden;
}

.stories-header__band {
  height: 56px;
  background: var(--yellow);
  border-bottom: 3px solid var(--black);
}

.stories-header__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 48px 32px 64px;
  display: grid;
  grid-template-columns: 58fr 42fr;
  gap: 24px;
  position: relative;
}

.stories-header__left .eyebrow {
  margin-bottom: 24px;
}

.stories-header__left h1 {
  font-size: clamp(48px, 6.5vw, 72px);
  line-height: 1.1;
}

.stories-header__left h1 .third {
  color: var(--coral);
}

.stories-header__left p {
  font-size: 18px;
  max-width: 52ch;
  margin-top: 24px;
}

.stories-header__shapes {
  position: relative;
  min-height: 280px;
}

.stories-header__shapes span {
  position: absolute;
}

.stories-header__shapes .a { top: 0; right: -40px; width: 180px; height: 180px; background: var(--peach); border-radius: 50%; }
.stories-header__shapes .b { top: 80px; left: -20px; width: 90px; height: 90px; background: var(--teal); border-radius: 50%; }
.stories-header__shapes .c { top: 60px; right: 80px; width: 60px; height: 60px; background: var(--yellow); border-radius: 50%; }
.stories-header__shapes .d { bottom: 8px; left: 80px; width: 60px; height: 50px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.stories-header__shapes .e { bottom: 30px; right: 16px; width: 60px; height: 60px; background: var(--peach); transform: rotate(45deg); }

.stories-header__shapes svg.zig {
  position: absolute;
  bottom: 24px;
  left: 24px;
  width: 100px;
  height: 30px;
}

/* Stories testimonial signature moment */
.testimonial-signature {
  position: relative;
  border-top: 4px solid var(--black);
  border-bottom: 4px solid var(--black);
}

.testimonial-signature__split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  position: relative;
  min-height: 480px;
}

.testimonial-signature__split--coral { background: var(--coral); }
.testimonial-signature__split--purple { background: var(--purple); }

.testimonial-signature__split .left,
.testimonial-signature__split .right {
  padding: 80px 64px 72px;
  position: relative;
}

.testimonial-signature__split .left {
  background: var(--coral);
}

.testimonial-signature__split .right {
  background: var(--purple);
}

.testimonial-signature__quote {
  position: absolute;
  top: 40px;
  left: 64px;
  right: 64px;
  bottom: 72px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: center;
  pointer-events: none;
}

.testimonial-signature__quote .eyebrow {
  color: var(--yellow);
  margin-bottom: 24px;
}

.testimonial-signature__quote h2 {
  font-size: clamp(40px, 6.5vw, 80px);
  color: var(--white);
  line-height: 1.05;
}

.testimonial-signature__sub {
  background: var(--cream);
  padding: 64px 80px 80px;
}

.testimonial-signature__sub h3 {
  font-size: clamp(24px, 3vw, 32px);
  color: var(--purple);
  margin-bottom: 16px;
}

.testimonial-signature__sub p {
  font-size: 17px;
  max-width: 64ch;
}

.testimonial-signature__sub::after {
  content: "";
  display: block;
  width: 120px;
  height: 4px;
  background: var(--coral);
  margin-top: 32px;
}

/* Stories grid */
.stories-grid-section {
  background: var(--cream);
  padding: 80px 32px 0;
  text-align: center;
  position: relative;
}

.stories-grid-section__inner {
  max-width: 1080px;
  margin: 0 auto;
}

.stories-grid-section h2 {
  font-size: clamp(36px, 4.5vw, 56px);
  margin-top: 16px;
  margin-bottom: 48px;
}

.story-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  text-align: left;
}

.story-card {
  background: var(--white);
  border: 2px solid var(--black);
  display: flex;
  flex-direction: column;
}

.story-card__band {
  height: 80px;
  display: grid;
  place-items: center;
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  font-weight: 700;
  text-transform: uppercase;
  text-align: center;
  padding: 0 16px;
}

.story-card__band--coral  { background: var(--coral);  color: var(--white); }
.story-card__band--teal   { background: var(--teal);   color: var(--white); }
.story-card__band--yellow { background: var(--yellow); color: var(--black); }
.story-card__band--purple { background: var(--purple); color: var(--white); }

.story-card__body {
  padding: 24px;
}

.story-card__body h3 {
  font-size: 24px;
  line-height: 1.2;
  margin-bottom: 12px;
}

.story-card__body p {
  font-size: 16px;
  margin-bottom: 16px;
}

.story-card__meta {
  border-top: 1px solid var(--peach);
  padding-top: 16px;
  font-family: var(--f-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--peach);
}

.story-card__meta strong {
  color: var(--black);
  font-weight: 700;
}

.stories-grid-section__divider {
  margin: 48px auto 0;
  max-width: 240px;
  display: block;
}

.stories-cta-bar {
  background: var(--yellow);
  border-top: 4px solid var(--black);
  padding: 48px 32px;
  text-align: center;
  margin-top: 48px;
}

.stories-cta-bar h3 {
  font-size: clamp(28px, 3vw, 40px);
  margin-bottom: 20px;
}

/* ============================================
   BOOK PAGE
   ============================================ */
.book-header {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 480px;
  border-bottom: 4px solid var(--black);
  position: relative;
}

.book-header__cream,
.book-header__coral {
  padding: 64px 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
}

.book-header__cream {
  background: var(--cream);
}

.book-header__coral {
  background: var(--coral);
  color: var(--white);
  padding-left: 40px;
}

.book-header__cream .eyebrow {
  color: var(--teal);
  margin-bottom: 24px;
}

.book-header__cream p {
  font-size: 17px;
  max-width: 380px;
  margin-top: 20px;
}

.book-header__coral h1 {
  line-height: 1;
}

.book-header__coral .l1 {
  font-size: clamp(40px, 5vw, 64px);
  display: block;
}

.book-header__coral .l2 {
  font-size: clamp(64px, 9vw, 110px);
  display: block;
  color: var(--yellow);
  margin-left: -24px;
  line-height: 0.9;
  margin-top: 4px;
  margin-bottom: 4px;
}

.book-header__coral .l3 {
  font-size: clamp(40px, 5vw, 64px);
  display: block;
}

.book-header__decor {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.book-header__decor span,
.book-header__decor svg {
  position: absolute;
}

.book-header__decor .circ { width: 32px; height: 32px; background: var(--teal); border-radius: 50%; left: calc(50% - 16px); top: 15%; }
.book-header__decor .tri  { width: 28px; height: 26px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); right: 38%; bottom: 12%; }
.book-header__decor .sq1  { left: 30%; top: 20%; width: 200px; height: 80px; }
.book-header__decor .sq2  { left: 45%; top: 70%; width: 120px; height: 50px; }

/* Booking form section */
.booking-section {
  background: var(--cream);
  padding: 96px 32px 80px;
}

.booking-section__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: stretch;
}

.booking-form {
  background: var(--white);
  border: 3px solid var(--black);
  border-radius: 16px;
  padding: 40px;
  position: relative;
}

.booking-form__sticker {
  position: absolute;
  top: -10px;
  right: 32px;
  width: 24px;
  height: 24px;
  background: var(--yellow);
  border: 2px solid var(--black);
  border-radius: 50%;
}

.booking-form .eyebrow {
  color: var(--coral);
}

.booking-form h2 {
  font-size: clamp(36px, 4vw, 52px);
  margin-top: 12px;
}

.booking-form .sub {
  font-size: 16px;
  margin-top: 16px;
}

.booking-form .body {
  font-size: 15px;
  margin-top: 12px;
  color: rgba(26, 26, 26, 0.7);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-top: 24px;
}

.form-grid--full { grid-template-columns: 1fr; }

.field {
  display: flex;
  flex-direction: column;
}

.field label {
  font-family: var(--f-body);
  font-weight: 500;
  font-size: 13px;
  margin-bottom: 8px;
}

.field input,
.field select,
.field textarea {
  font-family: var(--f-body);
  font-size: 15px;
  color: var(--black);
  padding: 12px 14px;
  border: 2px solid var(--black);
  border-radius: 8px;
  background: var(--white);
  height: 48px;
  outline: none;
  transition: background 0.15s ease, box-shadow 0.15s ease;
}

.field textarea {
  height: auto;
  min-height: 86px;
  resize: vertical;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  background: var(--cream);
  box-shadow: 0 0 0 3px rgba(255, 214, 0, 0.5);
}

.day-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.day-pills label {
  cursor: pointer;
}

.day-pills input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.day-pills span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--f-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: var(--cream);
  border: 2px solid var(--black);
  padding: 8px 14px;
  border-radius: 999px;
  transition: background 0.12s ease, color 0.12s ease;
}

.day-pills input:checked + span {
  background: var(--yellow);
  color: var(--black);
}

.booking-info {
  background: var(--teal);
  color: var(--white);
  border: 3px solid var(--black);
  border-radius: 16px;
  padding: 32px;
  position: relative;
  overflow: hidden;
}

.booking-info__star {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 22px;
  height: 22px;
  border: 2px solid var(--yellow);
  transform: rotate(45deg);
}

.booking-info__list {
  position: relative;
  z-index: 2;
}

.booking-info__item + .booking-info__item {
  margin-top: 32px;
  padding-top: 32px;
  border-top: 1px solid rgba(255, 255, 255, 0.3);
}

.booking-info__item h3 {
  font-size: 22px;
  color: var(--white);
  margin-bottom: 6px;
}

.booking-info__item p {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.92);
}

.booking-info__squiggle {
  position: absolute;
  bottom: -8px;
  right: -8px;
  width: 120px;
  height: 80px;
  pointer-events: none;
}

/* Book section 3 */
.book-cta {
  background: var(--purple);
  color: var(--white);
  padding: 96px 32px;
  position: relative;
  overflow: hidden;
}

.book-cta__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 32px;
  position: relative;
  z-index: 2;
}

.book-cta__content .eyebrow {
  color: var(--yellow);
  margin-bottom: 14px;
}

.book-cta__content h2 {
  font-size: clamp(28px, 3.5vw, 40px);
  margin-bottom: 16px;
  max-width: 18ch;
  line-height: 1.1;
}

.book-cta__content p {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.85);
  max-width: 52ch;
  margin-bottom: 28px;
}

.book-cta__content p .em {
  color: var(--yellow);
  font-weight: 700;
}

.book-cta__buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.book-cta__decor {
  position: relative;
  min-height: 240px;
}

.book-cta__decor span,
.book-cta__decor svg {
  position: absolute;
}

.book-cta__decor .c1 { width: 80px; height: 80px; background: var(--teal); border-radius: 50%; top: 30%; left: 25%; }
.book-cta__decor .c2 { width: 60px; height: 40px; border: 3px solid var(--yellow); transform: rotate(15deg); top: 55%; left: 60%; }
.book-cta__decor .c3 { width: 40px; height: 36px; background: var(--peach); clip-path: polygon(50% 0, 100% 100%, 0 100%); bottom: 15%; left: 75%; }
.book-cta__decor svg  { top: 18%; left: 40%; width: 200px; }

/* ============================================
   PROGRAMS HEADER VARIANT
   ============================================ */
.programs-header {
  display: grid;
  grid-template-columns: 45fr 55fr;
  min-height: 480px;
  border-bottom: 4px solid var(--black);
}

.programs-header__coral {
  background: var(--coral);
  color: var(--white);
  padding: 48px 48px 64px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
}

.programs-header__cream {
  background: var(--cream);
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
}

.programs-header__coral .eyebrow {
  color: var(--white);
  margin-bottom: 24px;
}

.programs-header__coral h1 {
  font-size: clamp(40px, 6vw, 72px);
  color: var(--white);
}

.programs-header__cream p {
  font-size: 18px;
  max-width: 48ch;
}

.programs-header__cream .scatter {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.programs-header__cream .scatter span {
  position: absolute;
}

.programs-header__cream .scatter .p1 { top: 14%; right: 12%; width: 26px; height: 26px; background: var(--teal); border-radius: 50%; }
.programs-header__cream .scatter .p2 { top: 8%; right: 38%; width: 22px; height: 22px; background: var(--teal); border-radius: 50%; }
.programs-header__cream .scatter .p3 { top: 22%; right: 6%; width: 22px; height: 22px; background: var(--teal); border-radius: 50%; }
.programs-header__cream .scatter .p4 { top: 28%; right: 30%; width: 22px; height: 20px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.programs-header__cream .scatter .p5 { top: 34%; right: 18%; width: 18px; height: 16px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.programs-header__cream .scatter .p6 { top: 18%; right: 22%; width: 30px; height: 30px; background: var(--peach); transform: rotate(45deg); }
.programs-header__cream .scatter .p7 { top: 38%; right: 42%; width: 38px; height: 6px; background: var(--coral); border-radius: 6px; }
.programs-header__cream .scatter .p8 { top: 12%; right: 48%; width: 32px; height: 6px; background: var(--coral); border-radius: 6px; }

/* ============================================
   PRICING HEADER VARIANT
   ============================================ */
.pricing-page-header {
  display: grid;
  grid-template-columns: 55fr 45fr;
  min-height: 520px;
  border-bottom: 4px solid var(--black);
  position: relative;
  overflow: hidden;
}

.pricing-page-header__coral {
  background: var(--coral);
  color: var(--white);
  padding: 48px 56px 64px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}

.pricing-page-header__cream {
  background: var(--cream);
  padding: 80px 56px 64px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.pricing-page-header__coral .eyebrow {
  color: var(--white);
  margin-bottom: 16px;
}

.pricing-page-header__coral h1.line-1 {
  font-size: clamp(40px, 6vw, 76px);
  color: var(--white);
  margin-bottom: 8px;
  position: relative;
  z-index: 3;
}

.pricing-page-header__cream h1.line-2 {
  font-size: clamp(40px, 6vw, 76px);
  color: var(--black);
  position: relative;
  z-index: 3;
}

.pricing-page-header__cream p {
  font-size: 18px;
  max-width: 38ch;
  margin-top: 24px;
}

.pricing-page-header__decor span {
  position: absolute;
}

.pricing-page-header__decor .y1 { top: 12%; right: 8%; width: 18px; height: 18px; background: var(--yellow); border-radius: 50%; z-index: 4; }
.pricing-page-header__decor .y2 { top: 22%; right: 16%; width: 18px; height: 16px; background: var(--yellow); clip-path: polygon(50% 0, 100% 100%, 0 100%); z-index: 4; }
.pricing-page-header__decor .y3 { top: 32%; right: 6%; width: 22px; height: 12px; background: var(--yellow); z-index: 4; }
.pricing-page-header__decor .squiggle { bottom: 16px; left: 24px; width: 110px; height: 30px; }

/* ============================================
   PRICING LIST CTA - utility
   ============================================ */
.center-cta {
  display: flex;
  justify-content: center;
  margin-top: 48px;
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 960px) {
  .program-cards {
    grid-template-columns: repeat(2, 1fr);
  }
  .pricing-cards {
    grid-template-columns: 1fr;
    align-items: stretch;
  }
  .pricing-card--featured { transform: none; }
  .feature-cards {
    grid-template-columns: 1fr;
  }
  .feature-grid__header {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .feature-grid__head-right { grid-column: 1; }
  .booking-section__inner {
    grid-template-columns: 1fr;
  }
  .book-cta__inner {
    grid-template-columns: 1fr;
  }
  .book-cta__decor { display: none; }
  .faq-section__inner {
    grid-template-columns: 1fr;
  }
  .faq-list { grid-column: 1; margin-top: 32px; }
  .stories-header__inner { grid-template-columns: 1fr; }
  .stories-header__shapes { min-height: 200px; }
  .story-cards { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav__list { display: none; }
  .nav-toggle { display: block; }
  .nav__list.open {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    position: absolute;
    top: 100%;
    left: 0; right: 0;
    background: var(--cream);
    border-bottom: 3px solid var(--black);
    padding: 16px 32px;
  }
  .nav__list.open .nav__link {
    padding: 12px 0;
    border-radius: 0;
  }
  .nav__list.open .nav__link--active {
    background: transparent;
    color: var(--purple);
  }
  .nav__list.open .nav__cta {
    text-align: center;
    margin-top: 8px;
  }
  .hero {
    grid-template-columns: 1fr;
    min-height: auto;
  }
  .hero__panel {
    padding: 56px 24px;
  }
  .hero__panel--coral { padding-top: 64px; }
  .hero__squiggle {
    top: auto;
    bottom: -50px;
    right: 50%;
    transform: translateX(50%) rotate(90deg);
  }
  .page-header,
  .programs-header,
  .pricing-page-header,
  .book-header {
    grid-template-columns: 1fr;
    min-height: auto;
  }
  .page-header__panel,
  .programs-header__coral,
  .programs-header__cream,
  .pricing-page-header__coral,
  .pricing-page-header__cream,
  .book-header__cream,
  .book-header__coral {
    padding: 48px 24px;
  }
  .pricing-header__zero { left: 60%; bottom: -40px; font-size: 110px; }
  .testimonial-signature__split { grid-template-columns: 1fr; min-height: auto; }
  .testimonial-signature__split .left,
  .testimonial-signature__split .right { padding: 48px 28px; }
  .testimonial-signature__quote {
    position: relative;
    inset: auto;
    padding: 0;
  }
  .testimonial-signature__quote h2 { font-size: 40px; }
  .testimonial-signature__sub { padding: 48px 28px; }
  .program-cards { grid-template-columns: 1fr; }
  .programs-grid-section__watermark { display: none; }
  .form-grid { grid-template-columns: 1fr; }
  .booking-form { padding: 32px 24px; }
  .section__inner { padding: 64px 24px; }
  .cta-block { padding: 64px 24px; }
  .feature-grid { padding: 64px 24px; }
  .programs-grid-section { padding: 64px 24px; }
  .pricing-cards-section { padding: 56px 24px 80px; }
  .faq-section { padding: 64px 24px; }
  .booking-section { padding: 64px 24px; }
  .book-cta { padding: 64px 24px; }
  .stories-grid-section { padding: 56px 24px 0; }
  .site-footer { padding: 48px 24px 24px; }
  .site-footer__top {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .book-header__coral .l2 { margin-left: -8px; }
}

@media (max-width: 480px) {
  .hero__title { font-size: 56px; }
  .pricing-header__zero { font-size: 80px; }
  .stories-header__shapes { display: none; }
  .stories-header__inner { padding: 32px 24px 48px; }
}

